  "fr.f_narr": "ಟಿಪ್ಪಣಿ",
  "fr.cashwarn": "ವ್ಯಕ್ತಿ ಅಥವಾ ಫರ್ಮ್‌ನಿಂದ ₹20,000 ಅಥವಾ ಹೆಚ್ಚಿನ ಸಾಲವನ್ನು ಬ್ಯಾಂಕ್ ಟ್ರಾನ್ಸ್‌ಫರ್, ಚೆಕ್ ಅಥವಾ UPI ಮೂಲಕವೇ ತೆಗೆದುಕೊಳ್ಳಿ ಮತ್ತು ತೀರಿಸಿ, ನಗದಿನಲ್ಲಿ ಅಲ್ಲ (ಇನ್‌ಕಮ್ ಟ್ಯಾಕ್ಸ್ ನಿಯಮ).",
