  "fr.help2": "ತೆಗೆದುಕೊಂಡ ಸಾಲ ಬಾರೋಯಿಂಗ್ಸ್‌ನಲ್ಲಿ ಕಾಣುತ್ತದೆ. EMI ಯ ಅಸಲು ಭಾಗ ಮಾತ್ರ ಅದನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ; ಬಡ್ಡಿ ಭಾಗ ಫೈನಾನ್ಸ್ ಕಾಸ್ಟ್. ವರ್ಷಾಂತ್ಯದಲ್ಲಿ ಬ್ಯಾಂಕ್‌ನಿಂದ ಸಾಲದ ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಪಡೆಯಿರಿ.",
