  "hd.ownh": "ಪಟ್ಟಿಯಲ್ಲಿ ಇಲ್ಲದ ಹೆಡ್ ಸೇರಿಸಿ ಅದು ಯಾವ ಬಗೆಯದು ಎಂದು ಹೇಳಿ. ಖರ್ಚಿನ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಬರೆದ ಹೊಸ ಹೆಸರು ತಾನಾಗಿಯೇ ಇಲ್ಲಿ ಸೇರುತ್ತದೆ.",
