  "hd.blockw": "ಇದರ GST ಕ್ಲೈಮ್ ಮಾಡಲಾಗದು (CGST ಕಾಯ್ದೆ ಸೆಕ್ಷನ್ 17(5)). ಇನ್‌ಪುಟ್ ಟ್ಯಾಕ್ಸ್ ಕ್ರೆಡಿಟ್ ಟಿಕ್ ತೆಗೆಯಿರಿ.",
