  "app.d_oinc": "ಇತರ ಆದಾಯ",
  "ax.h": "ಗ್ರಾಹಕರಿಂದ ಬಾರದ ಹಣ, ಮತ್ತು ಸರ್ಕಾರಕ್ಕೆ ಕಟ್ಟಿದ ತೆರಿಗೆ. ಎರಡೂ ಇತರ ಎಂಟ್ರಿಗಳಂತೆ ನಿಮ್ಮ ಖಾತೆಗಳಿಗೆ ಹೋಗುತ್ತವೆ.",
  "ax.oinch": "ಮಾರಾಟವಲ್ಲದ ಆದಾಯಕ್ಕೆ: ಬಡ್ಡಿ, ಬಾಡಿಗೆ, ಕಮಿಷನ್, ಡಿವಿಡೆಂಡ್, ಸ್ಕ್ರ್ಯಾಪ್ ಮಾರಾಟ, ಇನ್ಶೂರೆನ್ಸ್ ಕ್ಲೈಮ್. ಗ್ರಾಹಕರ ಹಣ 'ಹಣ ಬಂತು'ನಲ್ಲಿ ಹಾಕಿ.",
