  "ax.payer": "ಯಾರಿಂದ ಬಂತು",
  "ax.notinc": "ಇದು ಖರ್ಚಿನ ಹೆಡ್. ಆದಾಯದ ಹೆಡ್ ಆರಿಸಿ.",
