  "ax.k_adv": "ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಅಥವಾ ಸೆಲ್ಫ್-ಅಸೆಸ್‌ಮೆಂಟ್ ಟ್ಯಾಕ್ಸ್",
