  "ax.kh_adv": "ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಜೂನ್ 15, ಸೆಪ್ಟೆಂಬರ್ 15, ಡಿಸೆಂಬರ್ 15, ಮಾರ್ಚ್ 15ರೊಳಗೆ; ಸೆಲ್ಫ್-ಅಸೆಸ್‌ಮೆಂಟ್ ಟ್ಯಾಕ್ಸ್ ರಿಟರ್ನ್ ಸಲ್ಲಿಸುವ ಮೊದಲು.",
  "ax.kh_gstref": "GST ಪೋರ್ಟಲ್ ನಿಮ್ಮ ಕ್ಯಾಶ್ ಲೆಡ್ಜರ್‌ನಿಂದ ಬ್ಯಾಂಕಿಗೆ ಹಿಂತಿರುಗಿಸಿದ ರೀಫಂಡ್.",
  "ax.kh_itref": "ಬ್ಯಾಂಕಿಗೆ ಬಂದ ಆದಾಯ ತೆರಿಗೆ ರೀಫಂಡ್.",
