  "ax.postq": "{p} ಯ GSTR-3B ಸೆಟ್-ಆಫ್ ಅನ್ನು {d} ದಿನಾಂಕದೊಂದಿಗೆ ಖಾತೆಗೆ ಸೇರಿಸಲೇ? ಔಟ್‌ಪುಟ್ ತೆರಿಗೆ {o} ತೀರಿದೆ: ಇನ್‌ಪುಟ್ ಕ್ರೆಡಿಟ್‌ನಿಂದ {c}, ನಗದಿನಿಂದ {k}. ರಿವರ್ಸ್ ಚಾರ್ಜ್ {r}, ಬಡ್ಡಿ ಮತ್ತು ಲೇಟ್ ಫೀ {f}. ರಿಟರ್ನ್ ಸಲ್ಲಿಸಿದ ನಂತರ ಮಾಡಿ; ಮತ್ತೆ ಸೇರಿಸಿದರೆ ಹಳೆಯದು ಬದಲಾಗುತ್ತದೆ.",
