  "w5.h_rent": "ನೀವು ಮನೆ ಮಾಲೀಕರು, ಬಾಡಿಗೆ ಈ ಬಿಸಿನೆಸ್‌ಗೆ ಬಂತು ಅಂದರೆ ಟಿಕ್ ಇಡಿ: ಬುಕ್ಸ್‌ನಲ್ಲಿ ಬಾಡಿಗೆ ಆದಾಯ ಆಗುತ್ತದೆ. ಬಾಡಿಗೆದಾರರ ಸಹಿಗಾಗಿ ಮಾಡಿದ ರಸೀದಿ ಆದರೆ ಟಿಕ್ ತೆಗೆಯಿರಿ.",
  "w5.h_petty": "ಕೊಟ್ಟ ಪ್ರತಿ ಖರ್ಚು ಅದರ ಹೆಡ್ ಮತ್ತು ದಿನಾಂಕದಲ್ಲಿ ಈ ಬಿಸಿನೆಸ್ ಬುಕ್ಸ್‌ಗೆ ಹೋಗುತ್ತದೆ. ಪೆಟ್ಟಿ ಕ್ಯಾಶ್‌ಗೆ ಹಾಕಿದ ಹಣ ಮತ್ತೆ ಎಣಿಸುವುದಿಲ್ಲ.",
