  "w5.h_erpf": "ಸಂಬಳದ ಮೇಲೆ ನಿಮ್ಮ ಸ್ವಂತ ಪಾಲು: ಬೇಸಿಕ್‌ನ 12%, ₹25,000 ವರೆಗೆ. \"PF, ESI, ಪ್ರೊಫೆಶನಲ್ ಟ್ಯಾಕ್ಸ್ ಮತ್ತು TDS ಲೆಕ್ಕ ಹಾಕಿ\" ಇದನ್ನು ತುಂಬುತ್ತದೆ.",
  "w5.eresi": "ಮಾಲೀಕರ ESI (₹)",
  "w5.paydate": "ಸಂಬಳ ಕೊಟ್ಟ ದಿನಾಂಕ",
