  "mk.start": "ಮಾರ್ಕೆಟ್‌ಪ್ಲೇಸ್ ನಿಮಗೆ ಎಷ್ಟು ಕೊಟ್ಟಿದೆ ಎಂದು ಚೆಕ್ ಮಾಡಿ",
  "mk.starth": "ಸೆಲ್ಲರ್ ಪೋರ್ಟಲ್‌ನಿಂದ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ ಪೇಔಟ್ (ಸೆಟಲ್‌ಮೆಂಟ್) ಫೈಲ್ ಅನ್ನು Excel ಅಥವಾ CSV ಆಗಿ ತೆರೆಯಿರಿ. ಇದನ್ನು ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಓದಲಾಗುತ್ತದೆ.",
  "mk.s1": "ಫೈಲ್ ತೆರೆಯಿರಿ. ಟೂಲ್ ಹೆಡಿಂಗ್‌ಗಳಿಂದ ಕಾಲಂಗಳನ್ನು ಹುಡುಕುತ್ತದೆ; ತಪ್ಪಾದ ಕಾಲಂ ಅನ್ನು ಬದಲಿಸಿ.",
  "mk.s2": "ಪ್ರತಿ ಆರ್ಡರ್ ಅನ್ನು ನಿಮ್ಮ ಸೇವ್ ಮಾಡಿದ ಇನ್‌ವಾಯ್ಸ್‌ಗಳ ಜೊತೆ ಮೊದಲು ಆರ್ಡರ್ ಐಡಿಯಿಂದ, ನಂತರ ಮೊತ್ತ ಮತ್ತು ದಿನಾಂಕದಿಂದ ಹೊಂದಿಸಲಾಗುತ್ತದೆ.",
  "mk.s3": "ರಿಟರ್ನ್‌ಗಳು, ಫೀಗಳು, TCS ಮತ್ತು TDS, ನೀವು ಬಿಲ್ ಮಾಡದ ಆರ್ಡರ್‌ಗಳು ಮತ್ತು ಪೇಔಟ್ ಸರಿಯಾಗಿ ಕೂಡುತ್ತದೆಯೇ ಎಂದು ನೋಡಿ.",
  "mk.layout": "ಪ್ರತಿ ಮಾರ್ಕೆಟ್‌ಪ್ಲೇಸ್ ಫೈಲ್‌ನ ಲೇಔಟ್ ಈ ಟೂಲ್‌ಗೆ ಗೊತ್ತಿಲ್ಲ ಮತ್ತು ಆಗಾಗ ಬದಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಫೈಲ್ ಸರಿಯಾಗಿ ಓದದಿದ್ದರೆ, “ಯಾವ ಕಾಲಂ ಯಾವುದು” ಅಡಿಯಲ್ಲಿ ಕಾಲಂಗಳನ್ನು ಕೈಯಾರೆ ಆರಿಸಿ, ಅಥವಾ ಇದು ಓದುವ ಎರಡು ರೂಪಗಳನ್ನು ನೋಡಲು ಉದಾಹರಣೆ ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ.",
  "mk.readfail": "ಈ ಫೈಲ್ ಓದಲು ಆಗಲಿಲ್ಲ. Excel (.xlsx) ಅಥವಾ CSV ಫೈಲ್ ಬಳಸಿ.",
