  "mk.taxnote": "TCS ಅನ್ನು ಮಾರಾಟದಿಂದ ರಿಟರ್ನ್‌ಗಳನ್ನು ಕಳೆದ, GST ಇಲ್ಲದ ಮೌಲ್ಯದ ಮೇಲೆ ಚೆಕ್ ಮಾಡಲಾಗುತ್ತದೆ. TDS ಅನ್ನು ಒಟ್ಟು ಮಾರಾಟದಿಂದ ರಿಟರ್ನ್‌ಗಳನ್ನು ಕಳೆದು ಚೆಕ್ ಮಾಡಲಾಗುತ್ತದೆ. ಸಣ್ಣ ಸೆಲ್ಲರ್‌ಗಳ ಆರ್ಡರ್‌ಗಳಿಗೆ TDS ವಿನಾಯಿತಿ ಇರಬಹುದು ಮತ್ತು ಸೆಲ್ಲರ್ ಬಳಿ ಕಡಿಮೆ ದರದ ಸರ್ಟಿಫಿಕೇಟ್ ಇರಬಹುದು. ಕ್ಲೇಮ್ ಮಾಡುವ ಮೊದಲು TCS ಕ್ರೆಡಿಟ್ ಅನ್ನು GST ಪೋರ್ಟಲ್‌ನಲ್ಲಿ (TCS credit received) ಮತ್ತು TDS ಅನ್ನು Form 26AS ಅಥವಾ AIS ನಲ್ಲಿ ಚೆಕ್ ಮಾಡಿ.",
