  "pr.rates_esi": "ವೇತನದ ಮೇಲೆ ನೌಕರ 0.75% ಮತ್ತು ಉದ್ಯೋಗದಾತ 3.25%, ಪ್ರತಿಯೊಂದನ್ನೂ ಮುಂದಿನ ರೂಪಾಯಿಗೆ ರೌಂಡ್ ಅಪ್ ಮಾಡಿ (Social Security (Central) Rules, 2026, rule 19). ವೇತನ ಮಿತಿ ತಿಂಗಳಿಗೆ ₹21,000: ಈಗಿನ ಮಿತಿಯನ್ನು ESIC ಸೈಟ್‌ನಲ್ಲಿ ಚೆಕ್ ಮಾಡಿ. ದಿನದ ವೇತನ ₹176 ಅಥವಾ ಕಡಿಮೆ ಇದ್ದರೆ ನೌಕರನ ಪಾಲು ಇಲ್ಲ (ESIC contribution ಪೇಜ್).",
