  "pr.pfintro": "ತಿಂಗಳ ಸ್ಯಾಲರಿ ಸ್ಲಿಪ್‌ಗಳಿಂದ EPFO unified portal ಗಾಗಿ ECR ಟೆಕ್ಸ್ಟ್ ಫೈಲ್ ಮತ್ತು ಚಲನ್ ಮೊತ್ತಗಳು ಆಗುತ್ತವೆ. ಮೊದಲು ಸ್ಲಿಪ್‌ಗಳನ್ನು ಮಾಡಿ (ಸ್ಯಾಲರಿ ಟ್ಯಾಬ್); ಸ್ಲಿಪ್ ಇಲ್ಲದ ನೌಕರರು ಕೆಳಗೆ ಲಿಸ್ಟ್ ಆಗಿದ್ದಾರೆ.",
  "pr.unver_pf": "ಅಪ್‌ಲೋಡ್ ಮಾಡುವ ಮೊದಲು ಚೆಕ್ ಮಾಡಿ: ಇದನ್ನು ಮಾಡಿದಾಗ (14 ನವೆಂಬರ್ 2026) EPFO ನ ಸ್ವಂತ ಫೈಲ್-ರಚನೆ ಡಾಕ್ಯುಮೆಂಟ್ ತೆರೆಯಲು ಆಗಲಿಲ್ಲ. 11 ಫೀಲ್ಡ್‌ಗಳು ಮತ್ತು ಅವುಗಳ ಕ್ರಮ ಪೇರೋಲ್ ಸಾಫ್ಟ್‌ವೇರ್ ತಯಾರಕರು ಪ್ರಕಟಿಸುವುದನ್ನು ಅನುಸರಿಸುತ್ತವೆ. ಫೈಲ್ ಅನ್ನು EPFO ಪೋರ್ಟಲ್‌ನ ECR ಪೇಜ್‌ಗೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿ; ಪೋರ್ಟಲ್ ಯಾವುದೇ ಸಾಲನ್ನು ತಿರಸ್ಕರಿಸಿದರೆ ಕಾರಣ ಹೇಳುತ್ತದೆ.",
