  "it.f_oth_h": "ಬಡ್ಡಿ, ಇತರರಿಂದ ಬಾಡಿಗೆ ಮತ್ತು ನಿಮ್ಮ ಲೆಕ್ಕದಲ್ಲಿ ಇತರೆ ಆದಾಯ ಎಂದು ಬರೆದ ಇಂಥ ಆದಾಯ, ಇಡೀ ವರ್ಷಕ್ಕೆ ವಿಸ್ತರಿಸಿ.",
  "it.f_sal": "ಸಂಬಳ ಅಥವಾ ಪೆನ್ಶನ್",
  "it.f_sal_h": "ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಡಿಡಕ್ಷನ್‌ಗೆ ಮೊದಲು.",
  "it.f_house": "ಮನೆ ಪ್ರಾಪರ್ಟಿಯಿಂದ ಆದಾಯ",
  "it.f_house_h": "ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಡಿಡಕ್ಷನ್ ಮತ್ತು ಹೋಮ್ ಲೋನ್ ಬಡ್ಡಿ ಕಳೆದು; ನಷ್ಟವನ್ನು ಮೈನಸ್ ಚಿಹ್ನೆಯೊಂದಿಗೆ ಟೈಪ್ ಮಾಡಿ.",
  "it.f_cg": "ಸಾಮಾನ್ಯ ದರದ ಕ್ಯಾಪಿಟಲ್ ಗೇನ್ಸ್",
  "it.f_cg_h": "ವಿಶೇಷ ದರದಲ್ಲಿ ತೆರಿಗೆ ಇರುವ ಗೇನ್ಸ್ (ಶೇರುಗಳು, ಈಕ್ವಿಟಿ ಫಂಡ್‌ಗಳು, ಪ್ರಾಪರ್ಟಿ) ಇಲ್ಲಿ ಲೆಕ್ಕ ಹಾಕಲಾಗುವುದಿಲ್ಲ.",
  "it.f_80c": "ಹಳೆಯ ರೆಜಿಮ್: 80C ರೀತಿಯ ಡಿಡಕ್ಷನ್‌ಗಳು",
  "it.f_80c_h": "PF, ಲೈಫ್ ಇನ್ಶೂರೆನ್ಸ್, ಟ್ಯಾಕ್ಸ್ ಸೇವಿಂಗ್ ಫಂಡ್‌ಗಳು ಇತ್ಯಾದಿ; ₹1,50,000 ಮಿತಿ. Income-tax Act 2025 ರಲ್ಲಿ section 123.",
  "it.f_dedo": "ಹಳೆಯ ರೆಜಿಮ್: ಇತರೆ ಡಿಡಕ್ಷನ್‌ಗಳು",
  "it.f_dedo_h": "ಹೆಲ್ತ್ ಇನ್ಶೂರೆನ್ಸ್, ಸ್ವಂತ ವಾಸದ ಮನೆಯ ಹೋಮ್ ಲೋನ್ ಬಡ್ಡಿ, ಹೆಚ್ಚುವರಿ NPS ಇತ್ಯಾದಿ, ನೀವೇ ಕೂಡಿಸಿ.",
  "it.f_nps": "ಉದ್ಯೋಗದಾತನ NPS ಕಾಂಟ್ರಿಬ್ಯೂಶನ್",
  "it.f_nps_h": "ಎರಡೂ ರೆಜಿಮ್‌ಗಳಲ್ಲಿ ಅನುಮತಿ ಇದೆ; ಮೊತ್ತ ಟೈಪ್ ಮಾಡಿ.",
  "it.f_sur": "ಸರ್‌ಚಾರ್ಜ್",
  "it.f_sur_h": "ಲೆಕ್ಕ ಹಾಕಲಾಗುವುದಿಲ್ಲ. ನಿಮ್ಮ ಆದಾಯ ₹50 ಲಕ್ಷಕ್ಕಿಂತ ಹೆಚ್ಚಿದ್ದರೆ ಮೊತ್ತ ಟೈಪ್ ಮಾಡಿ.",
  "it.f_tds": "ಈ ಆದಾಯದ ಮೇಲೆ ಕಡಿತವಾದ TDS ಮತ್ತು TCS",
  "it.f_tds_h": "ವರ್ಷದ ನಿಮ್ಮ ರಸೀದಿಗಳು ಮತ್ತು ಇತರೆ ಆದಾಯದಲ್ಲಿ ದಾಖಲಾದ TDS ನಿಂದ ಶುರುವಾಗುತ್ತದೆ. ಇನ್ನೂ ಕಡಿತವಾಗಬೇಕಾದ್ದನ್ನು ಸೇರಿಸಿ.",
  "it.f_def": "ನಂತರ ಬರುವ ಗೇನ್ಸ್ ಅಥವಾ ಲಾಭದ ಮೇಲಿನ ತೆರಿಗೆ",
  "it.f_mon": "ತೆರಿಗೆ ಕಡಿಮೆ ಕಟ್ಟಿದರೆ ಬಡ್ಡಿಯ ತಿಂಗಳುಗಳು",
  "it.f_mon_h": "ವರ್ಷದ ನಂತರದ 1 ಏಪ್ರಿಲ್‌ನಿಂದ ರಿಟರ್ನ್ ಪ್ರೊಸೆಸ್ ಆಗುವ ದಿನದವರೆಗೆ. 4 = 31 ಜುಲೈ ಒಳಗೆ ಫೈಲ್ ಮಾಡಿದ ರಿಟರ್ನ್.",
  "it.m_senior": "ಬಿಸಿನೆಸ್ ಅಥವಾ ಪ್ರೊಫೆಶನ್ ಆದಾಯ ಇಲ್ಲದ 60 ಅಥವಾ ಹೆಚ್ಚು ವಯಸ್ಸಿನ ನಿವಾಸಿ ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಕಟ್ಟಬೇಕಿಲ್ಲ (section 403(3)). ರಿಟರ್ನ್ ಫೈಲ್ ಮಾಡುವಾಗ ಬಾಕಿ ಕಟ್ಟಿ.",
  "it.m_below": "TDS ನಂತರದ ತೆರಿಗೆ {n}, ₹10,000 ಕ್ಕಿಂತ ಕಡಿಮೆ, ಹಾಗಾಗಿ ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಬೇಕಿಲ್ಲ (section 404). ರಿಟರ್ನ್ ಫೈಲ್ ಮಾಡುವಾಗ ಬಾಕಿ ಕಟ್ಟಿ.",
  "it.m_pres": "ಪ್ರಿಸಂಪ್ಟಿವ್ ಸ್ಕೀಮ್‌ನಲ್ಲಿ ಇಡೀ ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಅನ್ನು 15 ಮಾರ್ಚ್ ಒಳಗೆ ಕಟ್ಟಲಾಗುತ್ತದೆ (section 408(2)).",
  "it.m_sur": "ನಿಮ್ಮ ಆದಾಯ ₹50 ಲಕ್ಷಕ್ಕಿಂತ ಹೆಚ್ಚಿದೆ: ಸರ್‌ಚಾರ್ಜ್ ಟೈಪ್ ಮಾಡಿ, ಅದನ್ನು ಇಲ್ಲಿ ಲೆಕ್ಕ ಹಾಕಲಾಗುವುದಿಲ್ಲ.",
  "it.m_past": "ಈ ವರ್ಷ ಮುಗಿದಿದೆ. 31 ಮಾರ್ಚ್ ನಂತರ ಕಟ್ಟಿದ ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಅದಕ್ಕೆ ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ ಆಗಿ ಎಣಿಕೆಯಾಗುವುದಿಲ್ಲ; ಕೆಳಗಿನ ಬಡ್ಡಿ ಕೊರತೆಯ ವೆಚ್ಚ ತೋರಿಸುತ್ತದೆ.",
  "it.m_season": "ಅಂದಾಜು ಇಲ್ಲಿಯವರೆಗಿನ ಲಾಭವನ್ನು ನೇರ ರೇಖೆಯಲ್ಲಿ ಇಡೀ ವರ್ಷಕ್ಕೆ ವಿಸ್ತರಿಸುತ್ತದೆ. ನಿಮ್ಮ ಬಿಸಿನೆಸ್ ಸೀಸನಲ್ ಆಗಿದ್ದರೆ, ವರ್ಷದ ನಿಮ್ಮ ಸ್ವಂತ ಅಂಕಿ ಟೈಪ್ ಮಾಡಿ.",
