  "it.copyfail": "ಕಾಪಿ ಮಾಡಲು ಆಗಲಿಲ್ಲ: ಟೆಕ್ಸ್ಟ್ ಆರಿಸಿ ಕೈಯಾರೆ ಕಾಪಿ ಮಾಡಿ.",
  "it.csv": "Excel (CSV)",
  "it.print": "ಪ್ರಿಂಟ್",
  "it.basis": "ಈ ಅಂಕಿಗಳು ಯಾವುದರ ಮೇಲೆ ಆಧಾರಿತ ({d} ರಂತೆ)",
  "it.b1": "ದರಗಳು ({d} ರಂತೆ), ಟ್ಯಾಕ್ಸ್ ವರ್ಷ 2026-27: ಹೊಸ ರೆಜಿಮ್ ₹4 ಲಕ್ಷದವರೆಗೆ ಶೂನ್ಯ, ₹8 ಲಕ್ಷದವರೆಗೆ 5%, ₹12 ಲಕ್ಷದವರೆಗೆ 10%, ₹16 ಲಕ್ಷದವರೆಗೆ 15%, ₹20 ಲಕ್ಷದವರೆಗೆ 20%, ₹24 ಲಕ್ಷದವರೆಗೆ 25%, ಮೇಲೆ 30%; ₹12 ಲಕ್ಷದವರೆಗಿನ ಆದಾಯಕ್ಕೆ ತೆರಿಗೆ ಇಲ್ಲದಂತೆ ರಿಬೇಟ್, ಸ್ವಲ್ಪ ಮೇಲಿದ್ದರೆ ಮಾರ್ಜಿನಲ್ ರಿಲೀಫ್; ಸಂಬಳದ ಮೇಲೆ ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಡಿಡಕ್ಷನ್ ₹75,000. ಹಳೆಯ ರೆಜಿಮ್: ₹2.5 ಲಕ್ಷದವರೆಗೆ ಶೂನ್ಯ (60 ರಲ್ಲಿ ₹3 ಲಕ್ಷ, 80 ರಲ್ಲಿ ₹5 ಲಕ್ಷ), ₹5 ಲಕ್ಷದವರೆಗೆ 5%, ₹10 ಲಕ್ಷದವರೆಗೆ 20%, ಮೇಲೆ 30%; ₹5 ಲಕ್ಷದವರೆಗೆ ರಿಬೇಟ್ ₹12,500; ಸ್ಟ್ಯಾಂಡರ್ಡ್ ಡಿಡಕ್ಷನ್ ₹50,000. ಇವು ಸ್ಯಾಲರಿ ಸ್ಲಿಪ್ ಟೂಲ್ ಈಗಾಗಲೇ ಬಳಸುವ ದರಗಳು; ಈ ಬಿಲ್ಡ್‌ನಲ್ಲಿ Finance Act ನಿಂದ ಮತ್ತೆ ಓದಿಲ್ಲ, ಹಾಗಾಗಿ ಚೆಕ್ ಮಾಡಿ.",
  "it.b2": "ಅಡ್ವಾನ್ಸ್ ಟ್ಯಾಕ್ಸ್ (Income-tax Act 2025, sections 403 ರಿಂದ 408): TDS ನಂತರದ ತೆರಿಗೆ ₹10,000 ಅಥವಾ ಹೆಚ್ಚಿದ್ದಾಗ ಕಟ್ಟಬೇಕು; 15 ಜೂನ್ ಒಳಗೆ 15%, 15 ಸೆಪ್ಟೆಂಬರ್ ಒಳಗೆ 45%, 15 ಡಿಸೆಂಬರ್ ಒಳಗೆ 75%, 15 ಮಾರ್ಚ್ ಒಳಗೆ ಎಲ್ಲಾ; ಪ್ರಿಸಂಪ್ಟಿವ್ ತೆರಿಗೆದಾರ ಎಲ್ಲವನ್ನೂ 15 ಮಾರ್ಚ್ ಒಳಗೆ ಕಟ್ಟುತ್ತಾರೆ; 31 ಮಾರ್ಚ್ ವರೆಗಿನ ಪೇಮೆಂಟ್ ಆ ವರ್ಷಕ್ಕೆ ಎಣಿಕೆಯಾಗುತ್ತದೆ; ಬಿಸಿನೆಸ್ ಆದಾಯ ಇಲ್ಲದ 60 ಅಥವಾ ಹೆಚ್ಚು ವಯಸ್ಸಿನ ನಿವಾಸಿಗೆ ವಿನಾಯಿತಿ.",
  "it.b3": "ಬಡ್ಡಿ: section 424 (ಹಳೆಯ 234B) ತೆರಿಗೆಯ 90% ಕ್ಕಿಂತ ಕಡಿಮೆ ಕಟ್ಟಿದಾಗ ಕೊರತೆಯ ಮೇಲೆ ತಿಂಗಳಿಗೆ ಅಥವಾ ತಿಂಗಳ ಭಾಗಕ್ಕೆ 1%; section 425 (ಹಳೆಯ 234C) ಮೊದಲ ಮೂರು ಕಂತುಗಳ ಪ್ರತಿಯೊಂದರ ಕೊರತೆಯ ಮೇಲೆ 3% (15 ಜೂನ್ ಒಳಗೆ 12% ಮತ್ತು 15 ಸೆಪ್ಟೆಂಬರ್ ಒಳಗೆ 36% ಕಟ್ಟಿದ್ದರೆ ಇಲ್ಲ) ಮತ್ತು ಮಾರ್ಚ್ ಕೊರತೆಯ ಮೇಲೆ 1%.",
  "it.b5": "ಲೆಕ್ಕದ ಲಾಭ ತೆರಿಗೆಗೆ ಒಳಪಡುವ ಲಾಭ ಅಲ್ಲ: Act ಪ್ರಕಾರದ ಡಿಪ್ರಿಸಿಯೇಶನ್, ಅನುಮತಿಸದ ಖರ್ಚುಗಳು ಮತ್ತು ಪ್ರಿಸಂಪ್ಟಿವ್ ನಿಯಮಗಳು ಅದನ್ನು ಬದಲಿಸುತ್ತವೆ. ಈ ಪ್ಲಾನ್ ಮತ್ತು ಡೇಟಾ ಶೀಟ್ ಅನ್ನು ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ಗೆ ಕೊಡಿ.",
  "it.b6": "ಲೆಕ್ಕ ಹಾಕಿಲ್ಲ: ಸರ್‌ಚಾರ್ಜ್, ವಿಶೇಷ ದರದ ಕ್ಯಾಪಿಟಲ್ ಗೇನ್ಸ್, ವಿದೇಶಿ ತೆರಿಗೆ ರಿಲೀಫ್, ಅಪ್ರಾಪ್ತರ ಆದಾಯದ ಮೇಲಿನ ತೆರಿಗೆ, ಮತ್ತು ತಡವಾಗಿ ಫೈಲ್ ಮಾಡಿದ್ದಕ್ಕೆ ಬಡ್ಡಿ.",
  "it.b7": "ಏನೂ ಫೈಲ್ ಆಗುವುದಿಲ್ಲ, ನಿಮ್ಮ ಲೆಕ್ಕಕ್ಕೆ ಏನೂ ಸೇರುವುದಿಲ್ಲ.",
  "it.itr_h": "ಯಾವ ರಿಟರ್ನ್ ಫಾರ್ಮ್ ಹೊಂದುತ್ತದೆ, ಏಕೆ, ಮತ್ತು ಯಾವ ಪೇಪರ್‌ಗಳನ್ನು ರೆಡಿ ಇಡಬೇಕು ಎಂದು ನೋಡಲು ಕೆಲವು ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿ.",
  "it.use_form": "ಹೊಂದುವ ITR ಫಾರ್ಮ್: {f}",
  "it.q_who": "ಯಾರು ಫೈಲ್ ಮಾಡುತ್ತಿದ್ದಾರೆ",
