  "bi.postfail": "ಪೋಸ್ಟಿಂಗ್ ಅರ್ಧದಲ್ಲೇ ನಿಂತಿತು. ಸ್ಟೇಟ್‌ಮೆಂಟ್ ಅನ್ನು ಮತ್ತೆ ತೆರೆಯಿರಿ: ಈಗಾಗಲೇ ಪೋಸ್ಟ್ ಆದ ಸಾಲುಗಳು ಎರಡು ಬಾರಿ ಪೋಸ್ಟ್ ಆಗುವುದಿಲ್ಲ.",
  "bi.remember": "ಒಂದು ಸಾಲಿಗೆ ನೀವು ಖಚಿತಪಡಿಸಿದ ಪಾರ್ಟಿ ಅಥವಾ ಹೆಡ್ ನೆನಪಿರುತ್ತದೆ ಮತ್ತು ಮುಂದಿನ ಬಾರಿ ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ನಲ್ಲಿ ಅದೇ ಹೆಸರು ಬಂದಾಗ ಸೂಚಿಸಲಾಗುತ್ತದೆ.",
  "nav.ca": "ಅಕೌಂಟೆಂಟ್ ವ್ಯೂವರ್",
  "ca.mk": "ನನ್ನ ಅಕೌಂಟೆಂಟ್‌ಗೆ ಫೈಲ್ ಮಾಡಿ (ಓದಲು ಮಾತ್ರ)",
  "ca.t": "ನನ್ನ ಅಕೌಂಟೆಂಟ್‌ಗೆ ಫೈಲ್",
  "ca.intro": "ಒಂದು ಬಿಸಿನೆಸ್ ಮತ್ತು ಅವಧಿಯನ್ನು ಓದಲು ಮಾತ್ರ ಇರುವ ಒಂದೇ ಫೈಲ್ (.nsca) ಆಗಿ ಪ್ಯಾಕ್ ಮಾಡುತ್ತದೆ. ಅದನ್ನು ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ಗೆ WhatsApp ಅಥವಾ ಇಮೇಲ್ ಮೂಲಕ ಕಳುಹಿಸಿ. ಅವರು ಅದನ್ನು ca.niveshsahayak.in ನಲ್ಲಿ ತೆರೆದು, ಲೆಕ್ಕ ಓದಿ, ಪ್ರಶ್ನೆಗಳನ್ನು ಸೇರಿಸಿ, ಕಾಮೆಂಟ್‌ಗಳನ್ನು ನಿಮಗೆ ವಾಪಸ್ ಕಳುಹಿಸುತ್ತಾರೆ.",
  "ca.notlive": "ಇದು ಫೈಲ್ ಹಸ್ತಾಂತರ, ಲೈವ್ ಶೇರ್ಡ್ ಲಾಗಿನ್ ಅಲ್ಲ. ನೀವು ಫೈಲ್ ಮಾಡಿದಾಗ ಲೆಕ್ಕ ಹೇಗಿತ್ತೋ ಹಾಗೆಯೇ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ನೋಡುತ್ತಾರೆ. ಲೈವ್ ಲಾಗಿನ್‌ಗೆ ನಿಮ್ಮ ಲೆಕ್ಕ ಇಡುವ ಸರ್ವರ್ ಬೇಕು, Nivesh Sahayak ಬಳಿ ಅದು ಇಲ್ಲ: ನಿಮ್ಮ ಲೆಕ್ಕ ನಿಮ್ಮ ಡಿವೈಸ್‌ನಲ್ಲೇ ಇರುತ್ತದೆ. ಹೊಸ ಎಂಟ್ರಿಗಳಿಗೆ ಹೊಸ ಫೈಲ್ ಮಾಡಿ.",
  "ca.what": "ಏನೆಲ್ಲ ಸೇರುತ್ತದೆ",
  "ca.earlier": "ಮೊದಲ ದಿನಾಂಕಕ್ಕಿಂತ ಹಿಂದಿನ ಎಂಟ್ರಿಗಳು ಕೂಡ (ಆರಂಭದ ಬ್ಯಾಲೆನ್ಸ್ ಮತ್ತು ಏಜಿಂಗ್‌ಗೆ ಬೇಕು)",
  "ca.items": "ಖರೀದಿ ಮತ್ತು ಮಾರಾಟ ದರಗಳಿರುವ ಐಟಂ ಲಿಸ್ಟ್ (ಸ್ಟಾಕ್‌ಗೆ ಬೇಕು)",
  "ca.extra": "ನೀವು ಟಿಕ್ ಮಾಡಿದರೆ ಮಾತ್ರ",
  "ca.extrah": "ನೀವು ಟಿಕ್ ಮಾಡದಿದ್ದರೆ ಬಿಡಲಾಗುತ್ತದೆ. ಚಿತ್ರಗಳು (ಲೋಗೋ, ಸಹಿ), ನಿಮ್ಮ PIN ಮತ್ತು ಬ್ಯಾಕಪ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಎಂದಿಗೂ ಸೇರುವುದಿಲ್ಲ.",
  "ca.orders": "ಕೊಟೇಶನ್‌ಗಳು, ಪ್ರೊಫಾರ್ಮಾ ಇನ್‌ವಾಯ್ಸ್‌ಗಳು, ಸೇಲ್ಸ್ ಆರ್ಡರ್‌ಗಳು, ಚಲನ್‌ಗಳು ಮತ್ತು ಪರ್ಚೇಸ್ ಆರ್ಡರ್‌ಗಳು",
  "ca.staff": "ಸ್ಯಾಲರಿ ಸ್ಲಿಪ್‌ಗಳು, ಸಿಬ್ಬಂದಿ ಅಡ್ವಾನ್ಸ್, ಲೋನ್ ಮತ್ತು EMI, ಪೆಟ್ಟಿ ಕ್ಯಾಶ್, ಮತ್ತು ನೌಕರರ ಲಿಸ್ಟ್",
  "ca.phones": "ಪಾರ್ಟಿಗಳ ಫೋನ್ ನಂಬರ್, ಇಮೇಲ್ ವಿಳಾಸ ಮತ್ತು WhatsApp ನಂಬರ್",
  "ca.no.orders": "ಕೊಟೇಶನ್ ಮತ್ತು ಆರ್ಡರ್‌ಗಳು",
  "ca.no.staff": "ಸಂಬಳ ಮತ್ತು ಸಿಬ್ಬಂದಿ ರೆಕಾರ್ಡ್‌ಗಳು",
  "ca.no.phones": "ಫೋನ್ ನಂಬರ್ ಮತ್ತು ಇಮೇಲ್ ವಿಳಾಸಗಳು",
  "ca.no.bank": "ನಿಮ್ಮ ಬ್ಯಾಂಕ್ ಖಾತೆಯ ವಿವರ",
  "ca.note": "ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್‌ಗೆ ಒಂದು ಟಿಪ್ಪಣಿ (ಬೇಕಾದರೆ)",
  "ca.go": "ಫೈಲ್ ಮಾಡಿ",
  "ca.ready": "ಫೈಲ್ ರೆಡಿ: {n} ಎಂಟ್ರಿಗಳು, {p} ಪಾರ್ಟಿಗಳು, ಸುಮಾರು {kb} KB.",
  "ca.code": "ಚೆಕ್ ಕೋಡ್:",
  "ca.codeh": "ಈ ಕೋಡ್ ಅನ್ನು ನಿಮ್ಮ ಮೆಸೇಜ್‌ನಲ್ಲಿ ಕಳುಹಿಸಿ, ಅಥವಾ ಕಾಲ್‌ನಲ್ಲಿ ಓದಿ ಹೇಳಿ. ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಅದನ್ನು ಫೈಲ್ ತೋರಿಸುವ ಕೋಡ್ ಜೊತೆ ಹೋಲಿಸುತ್ತಾರೆ, ಹೀಗಾಗಿ ದಾರಿಯಲ್ಲಿ ಬದಲಾದ ಫೈಲ್ ಗೊತ್ತಾಗುತ್ತದೆ.",
