  "hm.me.tdsp": "ಮುಂದಿನ ತಿಂಗಳ 7 ರೊಳಗೆ ಕಟ್ಟಿ; ತ್ರೈಮಾಸಿಕ ಕೊನೆಯ ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ಗಳನ್ನು ಚೆಕ್ ಮಾಡಿ.",
