  "hm.me.backupp": "ಬ್ಯಾಕಪ್ ಫೈಲ್ ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ ಒಂದು ಪ್ರತಿಯನ್ನು ಈ ಡಿವೈಸ್‌ನ ಹೊರಗೆ ಇಡಿ.",
