/* Lines changed on 15 Nov 2026 (ESI template, income-tax source) */
NS.addLang("kn", {
  "pr.e_lastday": "ಈ ರೀಸನ್ ಕೋಡ್‌ಗೆ ಕೆಲಸದ ಕೊನೆಯ ದಿನ ಬೇಕು",
  "pr.unver_esi": "ಈ ಶೀಟ್ ESIC ಪೋರ್ಟಲ್‌ನ ಸ್ವಂತ Monthly Contribution ಟೆಂಪ್ಲೇಟ್‌ನಂತೆ ಇದೆ (15 ನವೆಂಬರ್ 2026ರಂದು ಪರಿಶೀಲಿಸಲಾಗಿದೆ): ಆರು ಕಾಲಂಗಳು ಟೆಕ್ಸ್ಟ್‌ನಲ್ಲಿ, Excel 97-2003 (.xls) ಫೈಲ್. ಈ ತಿಂಗಳು ಸಂಬಳ ಸಿಗದ ನೌಕರರೂ ರೀಸನ್ ಕೋಡ್ ಜೊತೆ ಪಟ್ಟಿಯಲ್ಲಿ ಬರುತ್ತಾರೆ. ಮೊದಲು ಒಂದು ತಿಂಗಳು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಪೋರ್ಟಲ್‌ನ ಫಲಿತಾಂಶ ನೋಡಿ.",
  "it.b4": "ಮೇಲಿನ ಸೆಕ್ಷನ್‌ಗಳನ್ನು 15 ನವೆಂಬರ್ 2026ರಂದು ಆದಾಯ ತೆರಿಗೆ ಇಲಾಖೆಯ ವೆಬ್‌ಸೈಟ್‌ನಲ್ಲಿರುವ (incometaxindia.gov.in) ಅಧಿಕೃತ ಪಠ್ಯದೊಂದಿಗೆ ಪದಕ್ಕೆ ಪದ ಹೋಲಿಸಿ ನೋಡಲಾಗಿದೆ. ಮುದ್ರಿತ ಕಾಯ್ದೆಯೇ ಅಂತಿಮ.",
  "it.f_def_h": "ಇನ್ನೂ ಗಳಿಸದ ಕ್ಯಾಪಿಟಲ್ ಗೇನ್, ಬಹುಮಾನ/ಲಾಟರಿ ಗೆಲುವು, ಡಿವಿಡೆಂಡ್ ಅಥವಾ ಮೊದಲ ವರ್ಷದ ವ್ಯಾಪಾರ ಲಾಭ: ಉಳಿದ ಕಂತುಗಳಲ್ಲಿ ಕಟ್ಟಿದರೆ ಹಿಂದಿನ ಕಂತುಗಳಲ್ಲಿ ಎಣಿಸುವುದಿಲ್ಲ (ಸೆಕ್ಷನ್ 425(4))."
});

